// =====================================================
//  YOUR SETTINGS - fill these in once
// =====================================================
return [{
  json: {
    candidateName: 'Alex Example',
    digestEmail: 'you@example.com',      // daily summary goes here

    // --- Where to search ---
    location: 'Berlin',                     // city/region ('' = anywhere)
    adzunaCountry: 'de',                    // de, at, gb, us, in, nl, fr ...
    adzunaAppId: 'YOUR_ADZUNA_APP_ID',      // free key: developer.adzuna.com
    adzunaAppKey: 'YOUR_ADZUNA_APP_KEY',
    maxDaysOld: 2,                          // only jobs posted in the last N days

    // Leave empty to let the AI build the searches from the CV.
    searchQueriesOverride: [],              // e.g. ['data analyst', 'werkstudent data']
    titleMustInclude: [],                   // e.g. ['analyst', 'analytics']
    excludeKeywords: ['unpaid', 'commission only', 'head of', 'director'],
    maxSearchQueries: 3,

    // --- AI ---
    modelScoring: 'claude-opus-5-5',        // reads every job (see README for cheaper choice)
    modelWriting: 'claude-opus-5-5',        // rewrites the CV and cover letter
    maxJobsToScore: 25,                     // max jobs the AI reads per run
    minScore: 70,                           // 0-100, only tailor + apply at or above this
    maxApplicationsPerDay: 5,
    applicationLanguage: 'auto',            // 'auto' = same language as the job ad

    // --- Applying ---
    // false = prepare everything and you press send (recommended at first)
    // true  = email the employer automatically when the ad gives an application email
    autoApplyByEmail: false,

    preferences: `Working student or junior role, 15-20 h/week during semester,
hybrid or remote, open to Berlin, Munich, Nuremberg. No pure sales roles.`,

    // Paste your full CV as plain text (include contact details).
    // The AI only uses facts from here.
    cvText: `ALEX EXAMPLE
alex@example.com | +49 000 000000 | Berlin | linkedin.com/in/alex-example

PROFILE
Business informatics student focused on data analysis and reporting.

SKILLS
Python (pandas, scikit-learn), SQL, Power BI, DAX, Excel

EXPERIENCE
Data Analyst Intern, Example GmbH, Berlin (03/2025 - 08/2025)
- Built 6 Power BI dashboards for the sales team
- Automated weekly reporting with Python, saving about 4 hours per week

EDUCATION
B.Sc. Business Informatics, Example University (expected 2026)

LANGUAGES
English C1, German B2`
  }
}];

// Step 1: ask Claude what to search for, based on the CV.
const cfg = $('Config').first().json;
const FALLBACK_MODELS = ['claude-opus-5-5', 'claude-sonnet-5-5', 'claude-fable-5-2', 'claude-opus-5'];

const body = {
  model: cfg.modelScoring,
  max_tokens: 4000,
  system: 'You are a career coach who knows how job boards work.',
  messages: [{ role: 'user', content: `Read this CV and the preferences, then plan a job search.

Country code: ${cfg.adzunaCountry}
Location: ${cfg.location || 'any'}

PREFERENCES:
${cfg.preferences}

CV:
${cfg.cvText}

Return:
- searchQueries: 1 to ${cfg.maxSearchQueries || 3} short job-board searches (1-3 words each) for the roles this person can realistically get. Use the words employers in that country put in job titles (for Germany, include German terms such as "Werkstudent" where it fits).
- titleKeywords: 3 to 10 lowercase single words or word stems; a relevant job title should contain at least one of them.` }],
  output_config: {
    effort: 'low',
    format: { type: 'json_schema', schema: {
      type: 'object',
      properties: {
        searchQueries: { type: 'array', items: { type: 'string' } },
        titleKeywords: { type: 'array', items: { type: 'string' } },
      },
      required: ['searchQueries', 'titleKeywords'],
      additionalProperties: false,
    } },
  },
};
if (FALLBACK_MODELS.includes(cfg.modelScoring)) body.fallbacks = 'default';
return [{ json: { requestBody: body } }];

// Turns the AI search plan into one item per search query.
const cfg = $('Config').first().json;
const res = $input.first().json || {};
let plan = { searchQueries: [], titleKeywords: [] };
const text = (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
try { plan = { ...plan, ...JSON.parse(text) }; } catch (e) { /* use overrides below */ }

const queries = (cfg.searchQueriesOverride || []).length ? cfg.searchQueriesOverride : plan.searchQueries;
const titleKeywords = (cfg.titleMustInclude || []).length ? cfg.titleMustInclude : plan.titleKeywords;

if (!queries.length) {
  const why = res.error ? JSON.stringify(res.error).slice(0, 300) : (res.stop_reason || 'no queries returned');
  throw new Error('Could not build a search from the CV (' + why + '). Check the Anthropic credential or fill searchQueriesOverride in Config.');
}
return queries.slice(0, cfg.maxSearchQueries || 3).map((q) => ({ json: { query: q, titleKeywords } }));

// Merges results from every job board, applies the keyword filter
// and skips jobs already handled in earlier runs.
const cfg = $('Config').first().json;
const titleKeywords = ($('Read Search Plan').first().json.titleKeywords || []).map((s) => String(s).toLowerCase().trim()).filter(Boolean);
const exclude = (cfg.excludeKeywords || []).map((s) => String(s).toLowerCase());

const clean = (s) => String(s || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ').trim();

const jobs = [];
for (const item of $input.all()) {
  const d = item.json || {};
  if (Array.isArray(d.results)) {            // Adzuna
    for (const r of d.results) jobs.push({
      source: 'Adzuna',
      title: clean(r.title),
      company: clean(r.company && r.company.display_name),
      location: clean(r.location && r.location.display_name),
      description: clean(r.description),
      url: r.redirect_url,
      salary: r.salary_min ? `${Math.round(r.salary_min)}-${Math.round(r.salary_max || r.salary_min)}` : '',
    });
  }
  if (Array.isArray(d.jobs)) {               // Remotive (remote jobs, full descriptions)
    for (const r of d.jobs) jobs.push({
      source: 'Remotive',
      title: clean(r.title),
      company: clean(r.company_name),
      location: clean(r.candidate_required_location) || 'Remote',
      description: clean(r.description),
      url: r.url,
      salary: clean(r.salary),
    });
  }
}

const store = $getWorkflowStaticData('global');   // persists for the active workflow
store.seen = store.seen || {};
const now = Date.now();
const TTL = 60 * 24 * 60 * 60 * 1000;            // forget jobs after 60 days
for (const k of Object.keys(store.seen)) if (now - store.seen[k] > TTL) delete store.seen[k];

const picked = [];
const thisRun = new Set();
for (const j of jobs) {
  if (!j.url || !j.title) continue;
  const title = ' ' + j.title.toLowerCase() + ' ';
  const text = (j.title + ' ' + j.description).toLowerCase();
  if (titleKeywords.length && !titleKeywords.some((k) => title.includes(k))) continue;
  if (exclude.some((x) => text.includes(x))) continue;
  const key = (j.title + '|' + j.company).toLowerCase();
  if (store.seen[key] || thisRun.has(key)) continue;
  thisRun.add(key);
  picked.push(j);
  if (picked.length >= (cfg.maxJobsToScore || 25)) break;
}
for (const j of picked) store.seen[(j.title + '|' + j.company).toLowerCase()] = now;

return picked.map((j) => ({ json: j }));

// Adds the text of the job's web page (job boards often only give a short summary).
const job = $('Clean, Filter & Dedupe').item.json;
const html = typeof $json.data === 'string' ? $json.data : '';
const pageText = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<(br|\/p|\/li|\/h\d|\/div)[^>]*>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim()
  .slice(0, 12000);
return { json: { ...job, pageText } };

// Step 2a: Claude scores the job against the CV and extracts the clean job description.
const cfg = $('Config').first().json;
const job = $json;
const FALLBACK_MODELS = ['claude-opus-5-5', 'claude-sonnet-5-5', 'claude-fable-5-2', 'claude-opus-5'];

const system = `You are an experienced recruiter screening job ads for one candidate.
Judge honestly how well each job fits the candidate's real experience, skills, seniority,
location, languages and preferences. Be strict: 70 or more means a realistic chance of an
interview; under 50 means they should not apply.

CANDIDATE PREFERENCES:
${cfg.preferences}

CANDIDATE CV:
${cfg.cvText}`;

const user = `JOB (from job board)
Title: ${job.title}
Company: ${job.company}
Location: ${job.location}
Salary: ${job.salary || 'not stated'}
Summary: ${job.description}

TEXT OF THE JOB WEB PAGE (may include menus and other noise, may be empty):
${job.pageText || '(not available)'}

Return:
- score: integer 0-100, overall fit (skills, experience, seniority, location, language, preferences)
- cvMatch: integer 0-100, ONLY how much of the job description's requirements and keywords the candidate's
  CV, exactly as written now, already covers (ignore location and preferences). 100 = every requirement
  is clearly shown in the CV; 0 = none.
- missingKeywords: up to 8 important skills or keywords from the job description that the CV does not show, comma separated, or "none"
- verdict: "strong", "possible" or "weak"
- reasons: at most 2 sentences on why it fits
- gaps: at most 2 sentences on what is missing, or "none"
- jobDescription: the job description as written in the ad (tasks, requirements, benefits), without website menus or cookie text; use the summary if the page text has nothing better; at most 900 words
- applyEmail: the email address the ad says to send applications to, or "" if there is none. Never guess one.
- adLanguage: language the ad is written in, e.g. "German" or "English"`;

const body = {
  model: cfg.modelScoring,
  max_tokens: 8000,
  system: [{ type: 'text', text: system, cache_control: { type: 'ephemeral' } }],
  messages: [{ role: 'user', content: user }],
  output_config: {
    effort: 'low',
    format: { type: 'json_schema', schema: {
      type: 'object',
      properties: {
        score: { type: 'integer' },
        cvMatch: { type: 'integer' },
        missingKeywords: { type: 'string' },
        verdict: { type: 'string', enum: ['strong', 'possible', 'weak'] },
        reasons: { type: 'string' },
        gaps: { type: 'string' },
        jobDescription: { type: 'string' },
        applyEmail: { type: 'string' },
        adLanguage: { type: 'string' },
      },
      required: ['score', 'cvMatch', 'missingKeywords', 'verdict', 'reasons', 'gaps', 'jobDescription', 'applyEmail', 'adLanguage'],
      additionalProperties: false,
    } },
  },
};
if (FALLBACK_MODELS.includes(cfg.modelScoring)) body.fallbacks = 'default';

const { pageText, ...jobWithoutPage } = job;
return { json: { job: jobWithoutPage, requestBody: body } };

// Reads Claude's score and job description.
const job = $('Prepare Score Request').item.json.job;
const res = $json || {};
let out = { score: 0, cvMatch: 0, missingKeywords: '', verdict: 'weak', reasons: '', gaps: '', jobDescription: '', applyEmail: '', adLanguage: '' };

if (res.error) {
  out.reasons = 'AI error: ' + JSON.stringify(res.error).slice(0, 300);
} else if (res.stop_reason === 'refusal') {
  out.reasons = 'AI declined to score this job.';
} else {
  const text = (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  try { out = { ...out, ...JSON.parse(text) }; } catch (e) { out.reasons = 'Could not read AI answer.'; }
}

return { json: {
  ...job,
  score: Number(out.score) || 0,
  cvMatch: Number(out.cvMatch) || 0,
  missingKeywords: out.missingKeywords,
  verdict: out.verdict,
  reasons: out.reasons,
  gaps: out.gaps,
  jobDescription: out.jobDescription || job.description,
  applyEmail: String(out.applyEmail || '').trim(),
  adLanguage: out.adLanguage,
} };

// Step 2b: row for the sheet - title + job description (keys = sheet column headers).
const cfg = $('Config').first().json;
const j = $json;
return { json: {
  'Job URL': j.url,
  'Date Found': new Date().toISOString().slice(0, 10),
  'Status': j.score >= (cfg.minScore || 70) ? 'Matched - preparing CV' : 'Low fit - skipped',
  'Fit Score': j.score,
  'CV Match (original CV)': j.cvMatch,
  'Missing Keywords': j.missingKeywords,
  'Title': j.title,
  'Company': j.company,
  'Location': j.location,
  'Source': j.source,
  'Job Description': String(j.jobDescription || '').slice(0, 45000),
  'Why it fits': j.reasons,
  'Gaps': j.gaps,
  'Apply Email': j.applyEmail,
} };

// Keeps only good matches, best first, up to the daily limit.
const cfg = $('Config').first().json;
return $('Read Score').all()
  .map((i) => i.json)
  .filter((j) => j.score >= (cfg.minScore || 70))
  .sort((a, b) => b.score - a.score)
  .slice(0, cfg.maxApplicationsPerDay || 5)
  .map((j) => ({ json: j }));

// Step 3: Claude rewrites the CV for this job description and writes the cover letter.
const cfg = $('Config').first().json;
const job = $json;
const FALLBACK_MODELS = ['claude-opus-5-5', 'claude-sonnet-5-5', 'claude-fable-5-2', 'claude-opus-5'];
const lang = (cfg.applicationLanguage && cfg.applicationLanguage !== 'auto')
  ? cfg.applicationLanguage : (job.adLanguage || 'the language of the job ad');

const system = `You tailor job applications for one candidate. Hard rules:
- Use ONLY facts from the candidate's CV. Never invent employers, dates, degrees, tools,
  certificates, numbers or achievements. If the job needs something the CV lacks, leave it out.
- You may reorder sections, rewrite bullet points, change emphasis and use the job ad's
  keywords where the CV supports them (this helps applicant tracking systems).
- Keep the candidate's contact details exactly as in the CV.
- No cliches ("I am writing to express my interest", "passionate team player").

CANDIDATE: ${cfg.candidateName}

CANDIDATE CV:
${cfg.cvText}`;

const user = `JOB AD
Title: ${job.title}
Company: ${job.company}
Location: ${job.location}

${job.jobDescription}

Screening notes - fits: ${job.reasons} Gaps: ${job.gaps}
Keywords the original CV does not show: ${job.missingKeywords} (add one only if the CV truly supports it)

Write everything in ${lang}. Return:
- tailoredCv: the complete improved CV as plain text, ready to paste into a document. Name and contact line first, then sections in CAPITALS (for example PROFILE, SKILLS, EXPERIENCE, EDUCATION, LANGUAGES), "- " for bullet points, max about 1 page.
- cvChanges: 2 to 4 short lines saying what you changed for this job
- coverLetter: at most 250 words, specific to this company and role, signed with the candidate's name
- emailSubject: subject line for an application email, e.g. "Application: <job title> - <name>"`;

const body = {
  model: cfg.modelWriting,
  max_tokens: 16000,
  system: [{ type: 'text', text: system, cache_control: { type: 'ephemeral' } }],
  messages: [{ role: 'user', content: user }],
  output_config: {
    effort: 'medium',
    format: { type: 'json_schema', schema: {
      type: 'object',
      properties: {
        tailoredCv: { type: 'string' },
        cvChanges: { type: 'string' },
        coverLetter: { type: 'string' },
        emailSubject: { type: 'string' },
      },
      required: ['tailoredCv', 'cvChanges', 'coverLetter', 'emailSubject'],
      additionalProperties: false,
    } },
  },
};
if (FALLBACK_MODELS.includes(cfg.modelWriting)) body.fallbacks = 'default';

return { json: { job, requestBody: body } };

// Reads the tailored CV and cover letter.
const cfg = $('Config').first().json;
const job = $('Prepare Tailor Request').item.json.job;
const res = $json || {};
let t = { tailoredCv: '', cvChanges: '', coverLetter: '', emailSubject: '' };
let problem = '';

if (res.error) problem = 'AI error: ' + JSON.stringify(res.error).slice(0, 300);
else if (res.stop_reason === 'refusal') problem = 'AI declined to write this application.';
else {
  const text = (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  try { t = { ...t, ...JSON.parse(text) }; } catch (e) { problem = 'Could not read AI answer.'; }
}

const safe = (s) => String(s || '').replace(/[\\/:*?"<>|]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60);
return { json: {
  job,
  ...t,
  problem,
  emailSubject: t.emailSubject || `Application: ${job.title} - ${cfg.candidateName}`,
  docName: `CV - ${safe(cfg.candidateName)} - ${safe(job.company)} - ${safe(job.title)}`,
  // Google Drive cannot create an empty file, so keep a placeholder on errors.
  docText: t.tailoredCv || ('CV could not be generated: ' + (problem || 'unknown error')),
} };

// Step 4: decide how to apply and attach the PDF.
const cfg = $('Config').first().json;
const t = $('Read Tailored CV').item.json;
const doc = $('Create CV Google Doc').item.json || {};
const binary = $input.item.binary || {};
const today = new Date().toISOString().slice(0, 10);

const safe = (s) => String(s || '').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 40);
const email = String(t.job.applyEmail || '').trim();
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const hasPdf = !!binary.data;
const ok = hasPdf && !!t.tailoredCv && !t.problem;
const sendNow = cfg.autoApplyByEmail === true && validEmail && ok;

if (hasPdf) binary.data.fileName = `CV_${safe(cfg.candidateName)}_${safe(t.job.company)}.pdf`;

const status = !ok ? 'Error - check CV' + (t.problem ? ': ' + t.problem : '')
  : sendNow ? 'Applied by email'
  : validEmail ? 'Ready - review and send email'
  : 'Ready - apply on company website';

return {
  json: {
    ...t,
    docLink: doc.id ? `https://docs.google.com/document/d/${doc.id}/edit` : '',
    sendNow,
    status,
    appliedOn: sendNow ? today : '',
  },
  binary,
};

// Step 5: write the improved CV and result back into the same sheet row.
const j = $json;
return { json: {
  'Job URL': j.job.url,
  'Status': j.status,
  'Tailored CV': j.tailoredCv,
  'CV Changes': j.cvChanges,
  'Cover Letter': j.coverLetter,
  'CV Doc Link': j.docLink,
  'Applied On': j.appliedOn,
} };

// One summary email for you.
const cfg = $('Config').first().json;
const rows = $('Decide How to Apply').all().map((i) => i.json);
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const nl = (s) => esc(s).replace(/\n/g, '<br>');
const today = new Date().toISOString().slice(0, 10);
const applied = rows.filter((r) => r.sendNow).length;

const btn = (href, label, color) => href
  ? `<a href="${esc(href)}" style="background:${color};color:#fff;padding:8px 14px;border-radius:4px;text-decoration:none;margin-right:8px">${label}</a>` : '';

const cards = rows.map((r) => `
<div style="border:1px solid #ddd;border-radius:8px;padding:16px;margin:0 0 16px">
  <h3 style="margin:0 0 4px">${esc(r.job.title)} &middot; ${esc(r.job.company)}</h3>
  <p style="margin:0 0 8px;color:#555">${esc(r.job.location)} &middot; Fit <b>${esc(r.job.score)}</b>/100 &middot; CV match <b>${esc(r.job.cvMatch)}%</b> &middot; <b>${esc(r.status)}</b></p>
  <p style="margin:0 0 8px"><b>Why it fits:</b> ${esc(r.job.reasons)}<br><b>Gaps:</b> ${esc(r.job.gaps)}<br><b>Missing in original CV:</b> ${esc(r.job.missingKeywords)}</p>
  <p style="margin:0 0 8px"><b>CV changes:</b><br>${nl(r.cvChanges)}</p>
  <p style="margin:12px 0">${btn(r.job.url, 'Open job', '#1a73e8')}${btn(r.docLink, 'Open tailored CV', '#188038')}</p>
  <details><summary><b>Cover letter</b></summary><p>${nl(r.coverLetter)}</p></details>
</div>`).join('');

const html = `<div style="font-family:Arial,sans-serif;max-width:680px">
<h2>${rows.length} tailored application${rows.length === 1 ? '' : 's'} for ${esc(cfg.candidateName)}</h2>
<p>${applied} sent by email automatically. The rest are ready: open the tailored CV, download it as PDF and apply with the job link. Everything is also in your tracking sheet.</p>
${cards}
<p style="color:#888;font-size:12px">CVs and letters are written by AI from your own CV. Check them before you send anything.</p>
</div>`;

return [{ json: { to: cfg.digestEmail, subject: `${rows.length} tailored applications for ${cfg.candidateName} - ${today}`, html } }];
